-- Run after upgrade_loyalty.sql on an existing prachuap_directory database.
USE prachuap_directory;
CREATE TABLE IF NOT EXISTS coupons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,place_slug VARCHAR(140) NULL,store_name VARCHAR(160) NOT NULL,title VARCHAR(180) NOT NULL,description VARCHAR(800) NOT NULL,point_cost INT UNSIGNED NOT NULL,starts_at DATETIME NULL,ends_at DATETIME NULL,max_redemptions INT UNSIGNED NULL,redeemed_count INT UNSIGNED NOT NULL DEFAULT 0,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_coupon_creator FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS coupon_redemptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,coupon_id BIGINT UNSIGNED NOT NULL,point_cost INT UNSIGNED NOT NULL,coupon_code VARCHAR(32) NOT NULL UNIQUE,status ENUM('issued','redeemed','cancelled') NOT NULL DEFAULT 'issued',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,redeemed_at TIMESTAMP NULL,UNIQUE KEY uniq_user_coupon (user_id,coupon_id),INDEX idx_redemption_user_created (user_id,created_at),CONSTRAINT fk_redemption_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_redemption_coupon FOREIGN KEY (coupon_id) REFERENCES coupons(id) ON DELETE RESTRICT) ENGINE=InnoDB;
ALTER TABLE loyalty_events MODIFY review_id BIGINT UNSIGNED NULL;
ALTER TABLE loyalty_events ADD COLUMN redemption_id BIGINT UNSIGNED NULL UNIQUE AFTER review_id;
ALTER TABLE loyalty_events MODIFY event_type ENUM('review_approved','review_not_approved','coupon_redeemed') NOT NULL;
ALTER TABLE loyalty_events ADD CONSTRAINT fk_loyalty_event_redemption FOREIGN KEY (redemption_id) REFERENCES coupon_redemptions(id) ON DELETE CASCADE;
